const QUIZ_CATS=["research","quranic","seerah","sahabah","ambiya","history"];

/* "Research" questions: riddle-style clues that send the reader to the seerah to find the answer. */
QUIZ_CURATED.push(
 {id:"r01",cat:"research",src:"seerah",ref:"Ibn Hisham, As-Sirah an-Nabawiyyah (Uhud); Ibn Sa'd, At-Tabaqat al-Kubra",q:{en:"Who is remembered as the \"Lady of Uhud\", the woman who fought to shield the Prophet ﷺ in that battle?",roman:"\"Khatoon-e-Uhud\" kaun thin, jinhon ne Uhud mein Nabi ﷺ ki hifazat ke liye jung ki?",ur:"\"خاتونِ احد\" کون تھیں، جنہوں نے احد میں نبی ﷺ کی حفاظت کے لیے جنگ کی؟"},
  o:[["Nusaybah bint Ka'b (Umm Ammarah) (RA)","نسیبہ بنت کعب (ام عمارہ) رضی اللہ عنہا"],["Khawlah bint al-Azwar","خولہ بنت الازور"],["Asma bint Abi Bakr (RA)","اسماء بنت ابی بکر رضی اللہ عنہا"],["Safiyyah bint Abdul-Muttalib (RA)","صفیہ بنت عبدالمطلب رضی اللہ عنہا"]],
  e:{en:"Nusaybah bint Ka'b (RA) came to Uhud to give water to the wounded; when the line broke she fought beside the Prophet ﷺ and was wounded many times.",roman:"Hazrat Nusaybah bint Ka'b (RA) Uhud mein zakhmiyon ko pani pilane aayi thin; jab saf toot gayi to Nabi ﷺ ke paas lareen aur kai zakhm khaye.",ur:"حضرت نسیبہ بنت کعب رضی اللہ عنہا احد میں زخمیوں کو پانی پلانے آئی تھیں؛ جب صف ٹوٹ گئی تو نبی ﷺ کے پاس لڑیں اور کئی زخم کھائے۔"}},
 {id:"r02",cat:"research",src:"seerah",ref:"Sahih al-Bukhari 2979",q:{en:"Which woman earned the title \"She of the Two Belts\" (Dhat an-Nitaqayn) during the Hijrah?",roman:"Hijrat ke dauran kis khatoon ko \"Zaat-un-Nitaqain\" (do kamarbandon wali) ka laqab mila?",ur:"ہجرت کے دوران کس خاتون کو \"ذات النطاقین\" کا لقب ملا؟"},
  o:[["Asma bint Abi Bakr (RA)","اسماء بنت ابی بکر رضی اللہ عنہا"],["Aishah (RA)","عائشہ رضی اللہ عنہا"],["Fatimah (RA)","فاطمہ رضی اللہ عنہا"],["Umm Salamah (RA)","ام سلمہ رضی اللہ عنہا"]],
  e:{en:"She tore her waist belt in two to tie up the food for the Prophet ﷺ and Abu Bakr (RA) as they left for the cave.",roman:"Unhon ne apna kamarband do hisson mein phaar kar Nabi ﷺ aur Hazrat Abu Bakr (RA) ka khana baandha jab woh ghaar ki taraf nikle.",ur:"انہوں نے اپنا کمربند دو حصوں میں پھاڑ کر نبی ﷺ اور حضرت ابو بکر رضی اللہ عنہ کا کھانا باندھا جب وہ غار کی طرف نکلے۔"}},
 {id:"r03",cat:"research",src:"seerah",ref:"Sahih al-Bukhari 3744",q:{en:"Which companion did the Prophet ﷺ call \"the trustworthy one of this ummah\" (Amin al-Ummah)?",roman:"Nabi ﷺ ne kis sahabi ko \"is ummat ka ameen\" kaha?",ur:"نبی ﷺ نے کس صحابی کو \"اس امت کا امین\" کہا؟"},
  o:[["Abu Ubaydah ibn al-Jarrah (RA)","ابو عبیدہ بن الجراح رضی اللہ عنہ"],["Uthman (RA)","عثمان رضی اللہ عنہ"],["Abdur-Rahman ibn Awf (RA)","عبدالرحمٰن بن عوف رضی اللہ عنہ"],["Sa'd ibn Abi Waqqas (RA)","سعد بن ابی وقاص رضی اللہ عنہ"]],
  e:{en:"\"Every nation has a trustworthy one, and the trustworthy one of this ummah is Abu Ubaydah ibn al-Jarrah.\"",roman:"\"Har ummat ka ek ameen hota hai, aur is ummat ke ameen Abu Ubaidah bin Jarrah hain.\"",ur:"\"ہر امت کا ایک امین ہوتا ہے، اور اس امت کے امین ابو عبیدہ بن الجراح ہیں۔\""}},
 {id:"r04",cat:"research",src:"seerah",ref:"Sahih al-Bukhari 3803",q:{en:"At whose death did the Throne of the Most Merciful shake, as the Prophet ﷺ said?",roman:"Nabi ﷺ ke farmaan ke mutabiq kis ki wafat par Arsh-e-Rahman hil gaya?",ur:"نبی ﷺ کے فرمان کے مطابق کس کی وفات پر عرشِ رحمٰن ہل گیا؟"},
  o:[["Sa'd ibn Mu'adh (RA)","سعد بن معاذ رضی اللہ عنہ"],["Hamzah (RA)","حمزہ رضی اللہ عنہ"],["Mus'ab ibn Umair (RA)","مصعب بن عمیر رضی اللہ عنہ"],["Ja'far ibn Abi Talib (RA)","جعفر بن ابی طالب رضی اللہ عنہ"]],
  e:{en:"Sa'd ibn Mu'adh (RA), chief of the Aws, died of a wound from the Battle of the Trench.",roman:"Aus ke sardar Hazrat Saad bin Muaz (RA) Jung-e-Khandaq ke zakhm se shaheed hue.",ur:"اوس کے سردار حضرت سعد بن معاذ رضی اللہ عنہ جنگِ خندق کے زخم سے شہید ہوئے۔"}},
 {id:"r05",cat:"research",src:"seerah",ref:"Ibn Hisham (Uhud)",q:{en:"Which martyr of Uhud was called \"the one washed by the angels\" (Ghasil al-Mala'ikah)?",roman:"Uhud ke kis shaheed ko \"Ghaseel-ul-Malaika\" (farishton ka ghusl diya hua) kaha gaya?",ur:"احد کے کس شہید کو \"غسیل الملائکہ\" کہا گیا؟"},
  o:[["Hanzalah ibn Abi Amir (RA)","حنظلہ بن ابی عامر رضی اللہ عنہ"],["Hamzah (RA)","حمزہ رضی اللہ عنہ"],["Anas ibn an-Nadr (RA)","انس بن نضر رضی اللہ عنہ"],["Abdullah ibn Jahsh (RA)","عبداللہ بن جحش رضی اللہ عنہ"]],
  e:{en:"Hanzalah (RA) rushed to Uhud on the morning after his wedding; the Prophet ﷺ said the angels were washing him.",roman:"Hazrat Hanzalah (RA) shadi ki agli subah Uhud ki taraf daure; Nabi ﷺ ne farmaya ke farishte unhein ghusl de rahe hain.",ur:"حضرت حنظلہ رضی اللہ عنہ شادی کی اگلی صبح احد کی طرف دوڑے؛ نبی ﷺ نے فرمایا کہ فرشتے انہیں غسل دے رہے ہیں۔"}},
 {id:"r06",cat:"research",src:"seerah",ref:"Sahih al-Bukhari 2846",q:{en:"\"Every prophet has a disciple (hawari), and my disciple is…\" — whom did the Prophet ﷺ name?",roman:"\"Har nabi ka ek hawari hota hai, aur mera hawari…\" Nabi ﷺ ne kis ka naam liya?",ur:"\"ہر نبی کا ایک حواری ہوتا ہے، اور میرا حواری…\" نبی ﷺ نے کس کا نام لیا؟"},
  o:[["Zubair ibn al-Awwam (RA)","زبیر بن العوام رضی اللہ عنہ"],["Talhah (RA)","طلحہ رضی اللہ عنہ"],["Ali (RA)","علی رضی اللہ عنہ"],["Bilal (RA)","بلال رضی اللہ عنہ"]],
  e:{en:"The Prophet ﷺ said this about Zubair (RA) when he volunteered to bring news of the enemy at the Trench.",roman:"Nabi ﷺ ne yeh Hazrat Zubair (RA) ke baare mein farmaya jab woh Khandaq mein dushman ki khabar laane ke liye aage bare.",ur:"نبی ﷺ نے یہ حضرت زبیر رضی اللہ عنہ کے بارے میں فرمایا جب وہ خندق میں دشمن کی خبر لانے کے لیے آگے بڑھے۔"}},
 {id:"r07",cat:"research",src:"seerah",ref:"Sahih al-Bukhari 4986",q:{en:"Which young scribe of revelation was given the task of gathering the Quran into one copy under Abu Bakr (RA)?",roman:"Wahi ke kis jawan katib ko Hazrat Abu Bakr (RA) ke daur mein Quran ek jagah jama karne ka kaam diya gaya?",ur:"وحی کے کس نوجوان کاتب کو حضرت ابو بکر رضی اللہ عنہ کے دور میں قرآن ایک جگہ جمع کرنے کا کام دیا گیا؟"},
  o:[["Zaid ibn Thabit (RA)","زید بن ثابت رضی اللہ عنہ"],["Ubayy ibn Ka'b (RA)","ابی بن کعب رضی اللہ عنہ"],["Abdullah ibn Mas'ud (RA)","عبداللہ بن مسعود رضی اللہ عنہ"],["Mu'adh ibn Jabal (RA)","معاذ بن جبل رضی اللہ عنہ"]],
  e:{en:"After many reciters were martyred at Yamamah, Abu Bakr (RA), on Umar's (RA) advice, asked Zaid ibn Thabit (RA) to collect the Quran.",roman:"Yamamah mein bohat se qari shaheed hue to Hazrat Umar (RA) ke mashware par Hazrat Abu Bakr (RA) ne Hazrat Zaid bin Sabit (RA) ko Quran jama karne ko kaha.",ur:"یمامہ میں بہت سے قاری شہید ہوئے تو حضرت عمر رضی اللہ عنہ کے مشورے پر حضرت ابو بکر رضی اللہ عنہ نے حضرت زید بن ثابت رضی اللہ عنہ کو قرآن جمع کرنے کو کہا۔"}},
 {id:"r08",cat:"research",src:"seerah",ref:"Sahih Muslim 2452",q:{en:"\"The first of you to join me will be the one with the longest hand.\" Which Mother of the Believers was it, \"long-handed\" in charity?",roman:"\"Tum mein se sab se pehle mujh se woh milegi jis ka haath sab se lamba hai.\" Kaunsi Umm-ul-Momineen thin, sadqe mein \"lambe haath\" wali?",ur:"\"تم میں سے سب سے پہلے مجھ سے وہ ملے گی جس کا ہاتھ سب سے لمبا ہے۔\" کون سی ام المؤمنین تھیں، صدقے میں \"لمبے ہاتھ\" والی؟"},
  o:[["Zaynab bint Jahsh (RA)","زینب بنت جحش رضی اللہ عنہا"],["Sawdah (RA)","سودہ رضی اللہ عنہا"],["Aishah (RA)","عائشہ رضی اللہ عنہا"],["Hafsah (RA)","حفصہ رضی اللہ عنہا"]],
  e:{en:"Zaynab bint Jahsh (RA) was the first of the Prophet's ﷺ wives to pass away after him; she worked with her hands and gave in charity.",roman:"Hazrat Zainab bint Jahsh (RA) Nabi ﷺ ke baad sab se pehle wafat paane wali zauja thin; woh haath se kaam karti aur sadqa deti thin.",ur:"حضرت زینب بنت جحش رضی اللہ عنہا نبی ﷺ کے بعد سب سے پہلے وفات پانے والی زوجہ تھیں؛ وہ ہاتھ سے کام کرتیں اور صدقہ دیتی تھیں۔"}},
 {id:"r09",cat:"research",src:"seerah",ref:"Ibn Hisham",q:{en:"Who was the first teacher the Prophet ﷺ sent to Madinah to teach Islam before the Hijrah?",roman:"Hijrat se pehle Nabi ﷺ ne Islam sikhane ke liye Madinah sab se pehle kis ko bheja?",ur:"ہجرت سے پہلے نبی ﷺ نے اسلام سکھانے کے لیے مدینہ سب سے پہلے کس کو بھیجا؟"},
  o:[["Mus'ab ibn Umair (RA)","مصعب بن عمیر رضی اللہ عنہ"],["Abdullah ibn Umm Maktum (RA)","عبداللہ بن ام مکتوم رضی اللہ عنہ"],["Mu'adh ibn Jabal (RA)","معاذ بن جبل رضی اللہ عنہ"],["Ammar ibn Yasir (RA)","عمار بن یاسر رضی اللہ عنہ"]],
  e:{en:"After the first Pledge of Aqabah, Mus'ab (RA) went to Yathrib, taught the Quran and many families accepted Islam.",roman:"Pehli Bait-e-Aqabah ke baad Hazrat Musab (RA) Yasrib gaye, Quran sikhaya aur bohat se gharane musalman hue.",ur:"پہلی بیعتِ عقبہ کے بعد حضرت مصعب رضی اللہ عنہ یثرب گئے، قرآن سکھایا اور بہت سے گھرانے مسلمان ہوئے۔"}},
 {id:"r10",cat:"research",src:"seerah",ref:"Ibn Hisham; Sahih Muslim 2053",q:{en:"In whose house did the Prophet ﷺ stay when he first arrived in Madinah?",roman:"Madinah pahunch kar Nabi ﷺ pehle kis ke ghar thehre?",ur:"مدینہ پہنچ کر نبی ﷺ پہلے کس کے گھر ٹھہرے؟"},
  o:[["Abu Ayyub al-Ansari (RA)","ابو ایوب انصاری رضی اللہ عنہ"],["Sa'd ibn Ubadah (RA)","سعد بن عبادہ رضی اللہ عنہ"],["Anas ibn Malik (RA)","انس بن مالک رضی اللہ عنہ"],["Ubayy ibn Ka'b (RA)","ابی بن کعب رضی اللہ عنہ"]],
  e:{en:"The Prophet's ﷺ camel knelt near the house of Abu Ayyub (RA), and he hosted the Prophet ﷺ until his own rooms were built.",roman:"Nabi ﷺ ki oontni Hazrat Abu Ayyub (RA) ke ghar ke paas baith gayi, aur woh hujron ki tameer tak aap ﷺ ke mezbaan rahe.",ur:"نبی ﷺ کی اونٹنی حضرت ابو ایوب رضی اللہ عنہ کے گھر کے پاس بیٹھ گئی، اور وہ حجروں کی تعمیر تک آپ ﷺ کے میزبان رہے۔"}},
 {id:"r11",cat:"research",src:"quran",ref:"Quran 80:1–10; Sunan at-Tirmidhi 3331",q:{en:"Surah Abasa begins with the story of a blind companion who came seeking guidance. Who was he?",roman:"Surah Abasa ek nabeena sahabi ke waqiye se shuru hoti hai jo hidayat ke liye aaye. Woh kaun the?",ur:"سورۃ عبس ایک نابینا صحابی کے واقعے سے شروع ہوتی ہے جو ہدایت کے لیے آئے۔ وہ کون تھے؟"},
  o:[["Abdullah ibn Umm Maktum (RA)","عبداللہ بن ام مکتوم رضی اللہ عنہ"],["Bilal ibn Rabah (RA)","بلال بن رباح رضی اللہ عنہ"],["Salman al-Farisi (RA)","سلمان فارسی رضی اللہ عنہ"],["Abu Dharr (RA)","ابو ذر رضی اللہ عنہ"]],
  e:{en:"Abdullah ibn Umm Maktum (RA) was blind; he later served as a muezzin alongside Bilal (RA).",roman:"Hazrat Abdullah bin Umm-e-Maktoom (RA) nabeena the; baad mein Hazrat Bilal (RA) ke saath muazzin bhi rahe.",ur:"حضرت عبداللہ بن ام مکتوم رضی اللہ عنہ نابینا تھے؛ بعد میں حضرت بلال رضی اللہ عنہ کے ساتھ مؤذن بھی رہے۔"}},
 {id:"r12",cat:"research",src:"seerah",ref:"Sahih al-Bukhari 3709",q:{en:"Which cousin of the Prophet ﷺ, martyred at Mu'tah, was given the name \"the one with two wings\" (At-Tayyar)?",roman:"Nabi ﷺ ke kis chachazad bhai ko, jo Mutah mein shaheed hue, \"Tayyar\" (do paron wale) kaha gaya?",ur:"نبی ﷺ کے کس چچا زاد بھائی کو، جو موتہ میں شہید ہوئے، \"طیار\" (دو پروں والے) کہا گیا؟"},
  o:[["Ja'far ibn Abi Talib (RA)","جعفر بن ابی طالب رضی اللہ عنہ"],["Zaid ibn Harithah (RA)","زید بن حارثہ رضی اللہ عنہ"],["Abdullah ibn Rawahah (RA)","عبداللہ بن رواحہ رضی اللہ عنہ"],["Aqil ibn Abi Talib (RA)","عقیل بن ابی طالب رضی اللہ عنہ"]],
  e:{en:"Ja'far (RA) lost both arms holding the banner at Mu'tah; the Prophet ﷺ said Allah gave him two wings in Paradise.",roman:"Hazrat Jafar (RA) ke dono baazu Mutah mein jhanda thame hue kat gaye; Nabi ﷺ ne farmaya Allah ne unhein Jannat mein do par diye.",ur:"حضرت جعفر رضی اللہ عنہ کے دونوں بازو موتہ میں جھنڈا تھامے ہوئے کٹ گئے؛ نبی ﷺ نے فرمایا اللہ نے انہیں جنت میں دو پر دیے۔"}},
 {id:"r13",cat:"research",src:"seerah",ref:"Musnad Ahmad 1740; Ibn Hisham",q:{en:"Who spoke for the Muslims before the Negus (An-Najashi) of Abyssinia and recited from Surah Maryam?",roman:"Habsha ke badshah Najashi ke saamne Musalmanon ki taraf se kis ne baat ki aur Surah Maryam parhi?",ur:"حبشہ کے بادشاہ نجاشی کے سامنے مسلمانوں کی طرف سے کس نے بات کی اور سورۃ مریم پڑھی؟"},
  o:[["Ja'far ibn Abi Talib (RA)","جعفر بن ابی طالب رضی اللہ عنہ"],["Uthman ibn Affan (RA)","عثمان بن عفان رضی اللہ عنہ"],["Abdullah ibn Mas'ud (RA)","عبداللہ بن مسعود رضی اللہ عنہ"],["Zubair (RA)","زبیر رضی اللہ عنہ"]],
  e:{en:"Ja'far (RA) explained Islam to the Negus and recited the opening of Surah Maryam; the Negus wept and protected the Muslims.",roman:"Hazrat Jafar (RA) ne Najashi ko Islam samjhaya aur Surah Maryam ki ibtidai ayat parhin; Najashi ro pare aur Musalmanon ko panah di.",ur:"حضرت جعفر رضی اللہ عنہ نے نجاشی کو اسلام سمجھایا اور سورۃ مریم کی ابتدائی آیات پڑھیں؛ نجاشی رو پڑے اور مسلمانوں کو پناہ دی۔"}},
 {id:"r14",cat:"research",src:"seerah",ref:"Ibn Hisham",q:{en:"Who looked after the Prophet ﷺ as a child, later married Zaid ibn Harithah (RA) and was the mother of Usamah (RA)?",roman:"Kaun thin jinhon ne bachpan mein Nabi ﷺ ki dekhbhal ki, baad mein Hazrat Zaid bin Haritha (RA) se nikah kiya aur Hazrat Usamah (RA) ki walida thin?",ur:"کون تھیں جنہوں نے بچپن میں نبی ﷺ کی دیکھ بھال کی، بعد میں حضرت زید بن حارثہ رضی اللہ عنہ سے نکاح کیا اور حضرت اسامہ رضی اللہ عنہ کی والدہ تھیں؟"},
  o:[["Umm Ayman (Barakah) (RA)","ام ایمن (برکہ) رضی اللہ عنہا"],["Halimah as-Sa'diyyah (RA)","حلیمہ سعدیہ رضی اللہ عنہا"],["Fatimah bint Asad (RA)","فاطمہ بنت اسد رضی اللہ عنہا"],["Thuwaybah","ثویبہ"]],
  e:{en:"Barakah, known as Umm Ayman (RA), cared for him after his mother's death and remained close to his family all her life.",roman:"Hazrat Barakah, jo Umm-e-Ayman (RA) kehlati hain, walida ki wafat ke baad aap ﷺ ki dekhbhal karti rahin aur umr bhar ghar ke qareeb rahin.",ur:"حضرت برکہ، جو ام ایمن رضی اللہ عنہا کہلاتی ہیں، والدہ کی وفات کے بعد آپ ﷺ کی دیکھ بھال کرتی رہیں اور عمر بھر گھرانے کے قریب رہیں۔"}},
 {id:"r15",cat:"research",src:"seerah",ref:"Sahih al-Bukhari 3756",q:{en:"For which young companion did the Prophet ﷺ pray: \"O Allah, teach him the Book\"? He became known as the interpreter of the Quran.",roman:"Kis kam umr sahabi ke liye Nabi ﷺ ne dua ki: \"Aye Allah, isay Kitab ka ilm de\"? Woh Tarjuman-ul-Quran kehlaye.",ur:"کس کم عمر صحابی کے لیے نبی ﷺ نے دعا کی: \"اے اللہ، اسے کتاب کا علم دے\"؟ وہ ترجمان القرآن کہلائے۔"},
  o:[["Abdullah ibn Abbas (RA)","عبداللہ بن عباس رضی اللہ عنہ"],["Anas ibn Malik (RA)","انس بن مالک رضی اللہ عنہ"],["Abdullah ibn Umar (RA)","عبداللہ بن عمر رضی اللہ عنہ"],["Usamah ibn Zaid (RA)","اسامہ بن زید رضی اللہ عنہ"]],
  e:{en:"Ibn Abbas (RA) was a boy when the Prophet ﷺ made this dua; he became one of the greatest scholars of tafseer.",roman:"Jab Nabi ﷺ ne yeh dua ki to Hazrat Ibn Abbas (RA) bachche the; baad mein tafseer ke sab se bare ulama mein se hue.",ur:"جب نبی ﷺ نے یہ دعا کی تو حضرت ابن عباس رضی اللہ عنہ بچے تھے؛ بعد میں تفسیر کے سب سے بڑے علماء میں سے ہوئے۔"}},
 {id:"r16",cat:"research",src:"seerah",ref:"Sahih Muslim 1791",q:{en:"In which battle was the Prophet ﷺ wounded in the face and a tooth broken?",roman:"Kis jung mein Nabi ﷺ ka chehra mubarak zakhmi hua aur daant mubarak shaheed hua?",ur:"کس جنگ میں نبی ﷺ کا چہرۂ مبارک زخمی ہوا اور دندانِ مبارک شہید ہوا؟"},
  o:[["Uhud","احد"],["Badr","بدر"],["Hunayn","حنین"],["Khaybar","خیبر"]],
  e:{en:"At Uhud the Prophet ﷺ was struck in the face and his tooth was broken; he said: \"How can a people succeed who wound their prophet?\"",roman:"Uhud mein Nabi ﷺ ke chehre par zarb lagi aur daant mubarak toota; aap ne farmaya: \"Woh qaum kaise kamyab hogi jis ne apne nabi ko zakhmi kiya?\"",ur:"احد میں نبی ﷺ کے چہرے پر ضرب لگی اور دانت مبارک ٹوٹا؛ آپ نے فرمایا: \"وہ قوم کیسے کامیاب ہوگی جس نے اپنے نبی کو زخمی کیا؟\""}},
 {id:"r17",cat:"research",src:"seerah",ref:"Ibn Hisham",q:{en:"The Prophet's ﷺ kunyah \"Abul-Qasim\" comes from the name of whom?",roman:"Nabi ﷺ ki kunniyat \"Abul-Qasim\" kis ke naam se hai?",ur:"نبی ﷺ کی کنیت \"ابو القاسم\" کس کے نام سے ہے؟"},
  o:[["His son Qasim","آپ کے صاحبزادے قاسم"],["His grandfather","آپ کے دادا"],["His uncle Abu Talib","آپ کے چچا ابو طالب"],["A companion named Qasim","قاسم نام کے ایک صحابی"]],
  e:{en:"Qasim was the Prophet's ﷺ son from Khadijah (RA); he died in early childhood.",roman:"Qasim Hazrat Khadijah (RA) se Nabi ﷺ ke sahibzade the; bachpan hi mein wafat pa gaye.",ur:"قاسم حضرت خدیجہ رضی اللہ عنہا سے نبی ﷺ کے صاحبزادے تھے؛ بچپن ہی میں وفات پا گئے۔"}},
 {id:"r18",cat:"research",src:"seerah",ref:"Sunan Abi Dawud 1678; Jami at-Tirmidhi 3675",q:{en:"When the Prophet ﷺ asked for charity, which companion brought all his wealth, saying he had left Allah and His Messenger for his family?",roman:"Jab Nabi ﷺ ne sadqe ka hukm diya to kis sahabi ne apna saara maal pesh kar diya aur kaha ke ghar walon ke liye Allah aur us ka Rasool chhor aaya hoon?",ur:"جب نبی ﷺ نے صدقے کا حکم دیا تو کس صحابی نے اپنا سارا مال پیش کر دیا اور کہا کہ گھر والوں کے لیے اللہ اور اس کا رسول چھوڑ آیا ہوں؟"},
  o:[["Abu Bakr (RA)","ابو بکر رضی اللہ عنہ"],["Umar (RA)","عمر رضی اللہ عنہ"],["Uthman (RA)","عثمان رضی اللہ عنہ"],["Abdur-Rahman ibn Awf (RA)","عبدالرحمٰن بن عوف رضی اللہ عنہ"]],
  e:{en:"Umar (RA) brought half of his wealth hoping to surpass Abu Bakr (RA), who brought everything (Sunan Abi Dawud 1678, Tirmidhi 3675).",roman:"Hazrat Umar (RA) aadha maal laaye ke Abu Bakr (RA) se aage barh jayein, magar Hazrat Abu Bakr (RA) sab kuch le aaye (Abu Dawud 1678, Tirmizi 3675).",ur:"حضرت عمر رضی اللہ عنہ آدھا مال لائے کہ ابو بکر رضی اللہ عنہ سے آگے بڑھ جائیں، مگر حضرت ابو بکر رضی اللہ عنہ سب کچھ لے آئے (ابو داؤد 1678، ترمذی 3675)۔"}}
);
